@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  font-family:
    Inter,
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  color-scheme: light;
  background: #f6f8fa;
  color: #17202a;
  --aria-bg: #f6f8fa;
  --aria-panel: #ffffff;
  --aria-panel-muted: #fbfcfe;
  --aria-panel-subtle: #f1f5f9;
  --aria-ink: #17202a;
  --aria-ink-muted: #52616f;
  --aria-line: #dde5ec;
  --aria-line-strong: #c8d3dc;
  --aria-primary: #0891b2;
  --aria-primary-soft: #e0f7fb;
  --aria-success: #059669;
  --aria-success-soft: #dcfce7;
  --aria-warning: #d97706;
  --aria-warning-soft: #fef3c7;
  --aria-danger: #dc2626;
  --aria-danger-soft: #fee2e2;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--aria-bg);
}

#root {
  min-height: 100vh;
}

button,
select,
summary {
  cursor: pointer;
}

button:disabled,
select:disabled {
  cursor: not-allowed;
}

::selection {
  background: rgba(249, 115, 22, 0.28);
  color: #17202a;
}

.aria-lifecycle-card--deleting {
  pointer-events: none;
  animation: aria-lifecycle-card-delete-exit 220ms cubic-bezier(0.4, 0, 1, 1)
    forwards;
}

.aria-lifecycle-card--deleting button {
  cursor: progress;
}

@keyframes aria-lifecycle-card-delete-exit {
  from {
    opacity: 1;
    transform: translateX(0);
    filter: saturate(1);
  }

  to {
    opacity: 0.2;
    transform: translateX(4px);
    filter: saturate(0.7);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.001ms !important;
  }

  .aria-lifecycle-card--deleting {
    opacity: 0.55;
    transform: none;
  }
}

