      inputRef.current.value = "";
    }
  }

  return (
    <section
      aria-labelledby="image-create-reference-heading"
      className="rounded-xl border border-[var(--aria-line)] bg-[var(--aria-panel)] p-4 shadow-sm"
    >
      <h2 id="image-create-reference-heading" className="text-base font-semibold">
        参考图
      </h2>
      <p className="mt-1 text-xs text-[var(--aria-ink-muted)]">
        支持 PNG、JPEG、WebP，单张不超过 10MB。
      </p>
      {referenceImage && previewUrl ? (
        <div className="mt-3 overflow-hidden rounded-lg border border-[var(--aria-line)] bg-[var(--aria-panel-muted)]">
          <img
            src={previewUrl}
            alt="参考图预览"
            className="max-h-48 w-full object-contain"
          />
          <div className="flex items-center justify-between gap-3 border-t border-[var(--aria-line)] px-3 py-2">
            <span className="min-w-0 truncate text-xs text-[var(--aria-ink-muted)]">
              {referenceImage.name}
            </span>
            <button
              type="button"
              onClick={removeReference}
              disabled={isBusy}
              title={isBusy ? "处理中不可修改参考图" : undefined}
              className="shrink-0 rounded-md border border-[var(--aria-line)] bg-[var(--aria-panel)] px-2 py-1 text-xs font-semibold text-[var(--aria-danger)] transition-colors hover:border-[var(--aria-danger)] hover:bg-[var(--aria-danger-soft)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--aria-danger)] disabled:cursor-not-allowed disabled:opacity-50"
            >
              移除参考图
            </button>
          </div>
        </div>
      ) : (
        <label
          htmlFor={isBusy ? undefined : inputId}
          aria-disabled={isBusy}
          title={isBusy ? "处理中不可修改参考图" : undefined}
          className={`mt-3 flex flex-col items-center rounded-lg border border-dashed border-[var(--aria-line)] bg-[var(--aria-panel-muted)] px-4 py-6 text-center transition-colors ${
            isBusy
              ? "cursor-not-allowed opacity-60"
              : "cursor-pointer hover:border-[var(--aria-line-strong)] hover:bg-[var(--aria-panel)] focus-within:ring-2 focus-within:ring-[var(--aria-primary)]"
          }`}
        >
          <span className="text-sm font-semibold">选择一张参考图</span>
          <span className="mt-1 text-xs text-[var(--aria-ink-muted)]">点击浏览本地文件</span>
        </label>
      )}
      <input
        ref={inputRef}
        id={inputId}
        aria-label="上传参考图"
        type="file"
        accept={REFERENCE_IMAGE_MIME_TYPES.join(",")}
        disabled={isBusy}
        onChange={handleFileChange}
        className="sr-only"
      />
      {isBusy ? (
        <p className="mt-2 text-xs font-semibold text-[var(--aria-ink-muted)]">
          处理中不可修改参考图
        </p>
      ) : null}
      {error ? (
        <p role="alert" className="mt-2 text-sm font-semibold text-[var(--aria-danger)]">
          {error}
        </p>
      ) : null}
    </section>
  );
}

